// South African town list and headline matcher for the SA news layer.
// Town data is GeoNames (CC BY 4.0), generated by scripts/sa-towns.mjs.
import { readFileSync } from 'node:fs';

const TOWNS = Object.freeze(
  JSON.parse(readFileSync(new URL('./sa-towns.json', import.meta.url), 'utf8'))
    .towns,
);

