export const SA_DENY_PHRASES = Object.freeze(['Soweto derby']);

// Towns that a headline far more often means as something else. Headlines
// only: GDELT keeps placing these (its Newcastle is the KwaZulu-Natal town).
// Hand-kept, so never complete.
