// A town right after one of these words is part of a surname
// ("AB de Villiers"). Only the lower-case ("de") or Capitalised ("De") form
// counts: an all-caps word such as "DA" is a party or an acronym.
const SURNAME_PARTICLES = Object.freeze([
  'de',
  'du',
  'le',
  'la',
  'da',
  'van',
  'von',
  'der',
  'den',
]);
const PARTICLE_FORMS = SURNAME_PARTICLES.flatMap((p) => [
  p,
  p[0].toUpperCase() + p.slice(1),
]);

const DENIED = new Set(SA_DENY_NAMES.map((n) => n.toLowerCase()));
const HEADLINE_DENIED = new Set(
  SA_HEADLINE_DENY_NAMES.map((n) => n.toLowerCase()),
);

const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const BY_NAME = new Map(TOWNS.map((t) => [t.name, t]));
const TARGET = new Map(BY_NAME);
for (const [alias, name] of Object.entries(SA_ALIASES)) {
  TARGET.set(alias, BY_NAME.get(name));
}

// Denied names (both lists) take part in the scan so that a longer denied
// span ("Northern Cape", "Prince Albert") hides any shorter town inside it.
// Longest first makes the alternation pick the longest candidate at each
// position.
const CANDIDATES = [
  ...new Set([...TARGET.keys(), ...SA_DENY_NAMES, ...SA_HEADLINE_DENY_NAMES]),
]
  .sort((a, b) => b.length - a.length)
  .map(escapeRegExp);
const WORD = new RegExp(
  `(?<![\\p{L}\\p{N}])(?:${CANDIDATES.join('|')})(?![\\p{L}\\p{N}])`,
  'gu',
);
const PHRASES = new RegExp(SA_DENY_PHRASES.map(escapeRegExp).join('|'), 'gi');
// Text that ends in a surname particle and whitespace (case-sensitive: the
// lower-case and Capitalised forms only).
const AFTER_PARTICLE = new RegExp(
  `(?<![\\p{L}\\p{N}])(?:${PARTICLE_FORMS.join('|')})\\s+$`,
  'u',
);

/** Whether GDELT's place (or any name) is on the shared deny list. */
export function deniedPlace(name) {
  return DENIED.has(String(name).trim().toLowerCase());
}

/**
 * The town a headline names: the first whole-word town or alias in title
 * order, skipping denied names (both lists) and a name right after a surname
 * particle; a skipped name does not end the scan. A curly apostrophe (’) is
 * read as a straight one ('). Null when none.
 */
export function matchPlace(title) {
  const text = String(title ?? '')
    .replace(/’/g, "'")
    .replace(PHRASES, ' ');
  for (const match of text.matchAll(WORD)) {
    const [word] = match;
    if (deniedPlace(word) || HEADLINE_DENIED.has(word.toLowerCase())) continue;
    if (AFTER_PARTICLE.test(text.slice(0, match.index))) continue;
    const town = TARGET.get(word);
    if (town) return { name: town.name, lat: town.lat, lon: town.lon };
  }
  return null;
}

const SNAP_KM = 25;
const EARTH_KM = 6371;
const radians = (deg) => (deg * Math.PI) / 180;

/** Great-circle distance in km (haversine). */
function distanceKm(lat1, lon1, lat2, lon2) {
  const a =
    Math.sin(radians(lat2 - lat1) / 2) ** 2 +
    Math.cos(radians(lat1)) *
      Math.cos(radians(lat2)) *
      Math.sin(radians(lon2 - lon1) / 2) ** 2;
  return 2 * EARTH_KM * Math.asin(Math.min(1, Math.sqrt(a)));
}

/**
 * The listed town named exactly `name` when it lies within 25 km of
 * (lat, lon), else null. The list keeps only the most populous town of a
 * name, so one of that name further away is another place.
 */
export function townNear(name, lat, lon) {
  const town = BY_NAME.get(name);
  if (!town || !(distanceKm(lat, lon, town.lat, town.lon) <= SNAP_KM))
    return null;
  return { name: town.name, lat: town.lat, lon: town.lon };
}
